  const gone=s.gone||[],ids=Array.from({length:s.n+gone.length},(_,i)=>i+1).filter(k=>!gone.includes(k)).map(k=>s.pre+String(k).padStart(3,'0'));assert.equal(ids.length,s.n,t+' 문제 수');assert.deepEqual(Object.keys(bank).filter(id=>bank[id].topic===t).sort(),ids,t+'는 '+s.pre+'001~'+(s.n+gone.length)+(gone.length?'에서 뺀 번호 '+gone.join(', ')+' 말고 전부':''));
